// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/categories", wrapper.ListCategories)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/categories/{slug}", wrapper.GetCategory)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/products", wrapper.ListProducts)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/products/{slug}", wrapper.GetProduct)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/products/{slug}/reviews", wrapper.ListProductReviews)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/products/{slug}/related", wrapper.ListRelatedProducts)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/cart", wrapper.GetCart)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/cart/items", wrapper.AddCartItem)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/cart/items/{itemId}", wrapper.RemoveCartItem)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/cart/items/{itemId}", wrapper.UpdateCartItem)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/cart/addons", wrapper.SetCartAddons)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/cart/notes", wrapper.SetCartNotes)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/addons", wrapper.ListAddons)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/orders", wrapper.CreateOrder)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/orders/{ref}", wrapper.GetOrder)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/payments/mock/{providerOrderId}/complete", wrapper.CompleteMockPayment)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/payments/webhooks/{provider}", wrapper.ReceivePaymentWebhook)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/newsletter/subscriptions", wrapper.SubscribeNewsletter)

	return m
}

